using System;
using System.Collections.Generic;
using Framework.AI.Scheduling;
using Framework.Movement;
using Game.AI.Controllers;
using Game.AI.Parameters;
using Game.AI.Perception;
using UnityEngine;

namespace Game.Stage
{
    /// <summary>
    /// ステージに生成された敵とAIシステムを接続する。
    /// </summary>
    [DisallowMultipleComponent]
    public sealed class MazeEnemyStageBinder : MonoBehaviour
    {
        [Header("依存コンポーネント")]

        [SerializeField]
        [Tooltip("ステージ管理システム。")]
        private MazeStageManager stageManager;

        [SerializeField]
        [Tooltip("ステージオブジェクトの生成システム。")]
        private MazeStageSpawner stageSpawner;

        [SerializeField]
        [Tooltip("敵AIの思考更新管理システム。")]
        private AgentUpdateManager updateManager;

        [Header("敵プロファイル設定")]

        [SerializeField]
        [Tooltip("生成順に適用する敵プロファイル。")]
        private MazeEnemyProfile[] enemyProfiles;

        [SerializeField]
        [Tooltip("敵の数がプロファイル数を超えた場合に繰り返し使用する。")]
        private bool repeatProfiles = true;

        [Header("デバッグ設定")]

        [SerializeField]
        [Tooltip("敵AIの接続結果をログに出力する。")]
        private bool printDebugLog = true;

        [Header("実行時情報・確認専用")]

        [SerializeField]
        [Tooltip("接続済みの敵AIの数。")]
        private int boundEnemyCount;

        /// <summary>
        /// 接続済みの敵コントローラー。
        /// </summary>
        private readonly List<MazeEnemyController>
            enemies = new List<MazeEnemyController>();

        /// <summary>
        /// 認識対象候補の再利用バッファー。
        /// </summary>
        private readonly List<MazeEnemyTargetSnapshot>
            targetBuffer =
                new List<MazeEnemyTargetSnapshot>(4);

        /// <summary>
        /// プレイヤーの移動コントローラー。
        /// </summary>
        private GridMovementController playerMovement;

        /// <summary>
        /// 認識対象としてのプレイヤー識別子。
        /// </summary>
        private Guid playerId;

        /// <summary>
        /// 接続済みのステージ生成結果。
        /// </summary>
        private MazeStageGenerationResult boundStage;

        /// <summary>
        /// 接続処理を予約しているか。
        /// </summary>
        private bool bindRequested;

        /// <summary>
        /// 接続済みの敵AI数。
        /// </summary>
        public int BoundEnemyCount =>
            enemies.Count;

        /// <summary>
        /// 接続済みの敵コントローラー一覧。
        /// </summary>
        public IReadOnlyList<MazeEnemyController> Enemies =>
            enemies;

        /// <summary>
        /// プレイヤーの認識対象識別子。
        /// </summary>
        public Guid PlayerId => playerId;

        /// <summary>
        /// 接続先のステージ管理システム。
        /// </summary>
        public MazeStageManager StageManager =>
            stageManager;

        /// <summary>
        /// AI更新管理システム。
        /// </summary>
        public AgentUpdateManager UpdateManager =>
            updateManager;

        /// <summary>
        /// 必要なコンポーネントを取得する。
        /// </summary>
        private void Awake()
        {
            CacheComponents();
        }

        /// <summary>
        /// 未設定のコンポーネントを自身から取得する。
        /// </summary>
        private void CacheComponents()
        {
            if (stageManager == null)
            {
                stageManager =
                    GetComponent<MazeStageManager>();
            }

            if (stageSpawner == null)
            {
                stageSpawner =
                    GetComponent<MazeStageSpawner>();
            }

            if (updateManager == null)
            {
                updateManager =
                    GetComponent<AgentUpdateManager>();
            }
        }

        /// <summary>
        /// ステージ管理イベントを購読する。
        /// </summary>
        private void OnEnable()
        {
            CacheComponents();

            if (stageManager == null ||
                stageSpawner == null ||
                updateManager == null)
            {
                Debug.LogError(
                    "敵AI接続用コンポーネントが不足しています。",
                    this);

                return;
            }

            stageManager.StageGenerated +=
                HandleStageGenerated;

            stageManager.StateChanged +=
                HandleStageStateChanged;

            // 既にステージが存在する場合にも対応する。
            bindRequested = stageManager.HasStage;
        }

        /// <summary>
        /// ステージ生成完了時に接続を予約する。
        /// </summary>
        /// <param name="result">ステージ生成結果</param>
        private void HandleStageGenerated(
            MazeStageGenerationResult result)
        {
            ReleaseEnemies();

            bindRequested = true;
        }

        /// <summary>
        /// ステージ状態の変化を処理する。
        /// </summary>
        /// <param name="previous">変更前の状態</param>
        /// <param name="current">変更後の状態</param>
        private void HandleStageStateChanged(
            MazeStageState previous,
            MazeStageState current)
        {
            switch (current)
            {
                case MazeStageState.None:
                case MazeStageState.Generating:

                    ReleaseEnemies();

                    bindRequested = false;

                    break;

                case MazeStageState.Ready:
                case MazeStageState.Playing:

                    if (boundStage !=
                        stageManager.StageResult)
                    {
                        bindRequested = true;
                    }

                    break;
            }
        }

        /// <summary>
        /// 予約された敵AI接続処理を実行する。
        /// </summary>
        /// <remarks>
        /// 他のステージ接続処理とのイベント順序依存を避けるため、
        /// フレーム終了時に接続する。
        /// </remarks>
        private void LateUpdate()
        {
            if (!bindRequested)
            {
                return;
            }

            bindRequested = false;

            BindCurrentStage();
        }

        /// <summary>
        /// 現在のステージに敵AIを接続する。
        /// </summary>
        /// <returns>全敵の接続に成功した場合はtrue</returns>
        public bool BindCurrentStage()
        {
            if (!isActiveAndEnabled ||
                stageManager == null ||
                stageSpawner == null ||
                updateManager == null ||
                !stageManager.HasStage)
            {
                return false;
            }

            if (stageManager.State != MazeStageState.Ready &&
                stageManager.State != MazeStageState.Playing &&
                stageManager.State != MazeStageState.Paused)
            {
                return false;
            }

            ReleaseEnemies();

            bindRequested = false;

            MazeStageGenerationResult result =
                stageManager.StageResult;

            boundStage = result;

            // ステージごとに認識対象の識別子を更新する。
            playerId = Guid.NewGuid();

            CachePlayerMovement();

            var instances =
                stageSpawner.EnemyInstances;

            var spawnPositions =
                result.EnemySpawnPositions;

            int expectedCount =
                spawnPositions.Count;

            if (instances.Count != expectedCount)
            {
                Debug.LogError(
                    $"敵生成数と初期座標数が一致しません。" +
                    $" 生成数：{instances.Count}" +
                    $" 座標数：{expectedCount}",
                    this);

                return false;
            }

            bool allSucceeded = true;

            for (int i = 0; i < instances.Count; i++)
            {
                GameObject instance = instances[i];

                if (instance == null)
                {
                    allSucceeded = false;

                    continue;
                }

                var controller =
                    instance.GetComponent<MazeEnemyController>();

                if (controller == null)
                {
                    Debug.LogError(
                        $"{instance.name} に " +
                        "MazeEnemyControllerがありません。",
                        instance);

                    allSucceeded = false;

                    continue;
                }

                MazeEnemyProfile selectedProfile =
                    GetProfile(i);

                bool succeeded =
                    controller.Initialize(
                        stageManager,
                        updateManager,
                        spawnPositions[i],
                        GetTargetSnapshots,
                        selectedProfile);

                if (!succeeded)
                {
                    Debug.LogError(
                        $"敵AIの接続に失敗しました：" +
                        $"{instance.name}",
                        instance);

                    allSucceeded = false;

                    continue;
                }

                enemies.Add(controller);
            }

            boundEnemyCount = enemies.Count;

            if (printDebugLog)
            {
                Debug.Log(
                    $"【敵AI接続完了】" +
                    $" {boundEnemyCount}/{expectedCount}体",
                    this);
            }

            return allSucceeded;
        }

        /// <summary>
        /// 指定された生成番号のプロファイルを取得する。
        /// </summary>
        /// <param name="index">敵の生成番号</param>
        /// <returns>適用するプロファイル</returns>
        private MazeEnemyProfile GetProfile(int index)
        {
            if (enemyProfiles == null ||
                enemyProfiles.Length == 0)
            {
                return null;
            }

            if (index < enemyProfiles.Length)
            {
                return enemyProfiles[index];
            }

            if (repeatProfiles)
            {
                return enemyProfiles[
                    index % enemyProfiles.Length];
            }

            return null;
        }

        /// <summary>
        /// プレイヤーの移動コンポーネントを取得する。
        /// </summary>
        private void CachePlayerMovement()
        {
            GameObject player =
                stageSpawner.PlayerInstance;

            playerMovement = player != null
                ? player.GetComponent<GridMovementController>()
                : null;
        }

        /// <summary>
        /// 敵AIに認識対象候補を提供する。
        /// </summary>
        /// <returns>現在の認識対象候補一覧</returns>
        /// <remarks>
        /// 認識対象の候補情報であり、視認済み情報ではない。
        /// 返却するリストは再利用するため保持しないこと。
        /// </remarks>
        private IReadOnlyList<MazeEnemyTargetSnapshot>
            GetTargetSnapshots()
        {
            targetBuffer.Clear();

            if (stageManager == null ||
                !stageManager.IsPlaying)
            {
                return targetBuffer;
            }

            if (playerMovement == null)
            {
                CachePlayerMovement();
            }

            if (playerMovement != null &&
                playerMovement.IsInitialized &&
                playerMovement.isActiveAndEnabled &&
                playerId != Guid.Empty)
            {
                // 停止中のプレイヤーは速度0として扱う。
                bool moving =
                    playerMovement.IsMoving &&
                    !playerMovement.IsPaused;

                float speed = moving
                    ? playerMovement.MoveSpeed
                    : 0f;

                Vector2Int direction = moving
                    ? playerMovement.CurrentDirection
                    : Vector2Int.zero;

                targetBuffer.Add(
                    new MazeEnemyTargetSnapshot(
                        playerId,
                        MazeEnemyTargetType.Player,
                        playerMovement.CurrentCell,
                        direction,
                        speed));
            }

            return targetBuffer;
        }

        /// <summary>
        /// 接続済みの敵AIを解放する。
        /// </summary>
        public void ReleaseEnemies()
        {
            for (int i = 0; i < enemies.Count; i++)
            {
                MazeEnemyController controller =
                    enemies[i];

                if (controller != null)
                {
                    controller.Release();
                }
            }

            enemies.Clear();
            targetBuffer.Clear();

            boundEnemyCount = 0;
            boundStage = null;
            playerMovement = null;
            playerId = Guid.Empty;
        }

        /// <summary>
        /// 現在のステージに敵AIを再接続する。
        /// </summary>
        [ContextMenu("現在のステージに敵AIを再接続")]
        private void RebindFromInspector()
        {
            if (Application.isPlaying)
            {
                BindCurrentStage();
            }
        }

        /// <summary>
        /// 無効化時にイベント購読と敵AIを解放する。
        /// </summary>
        private void OnDisable()
        {
            if (stageManager != null)
            {
                stageManager.StageGenerated -=
                    HandleStageGenerated;

                stageManager.StateChanged -=
                    HandleStageStateChanged;
            }

            bindRequested = false;

            ReleaseEnemies();
        }

        /// <summary>
        /// オブジェクト破棄時に資源を解放する。
        /// </summary>
        private void OnDestroy()
        {
            ReleaseEnemies();
        }
    }
}
